class Solution {
    public boolean isSymmetric(TreeNode root) {
        return same(root, mirrorCopy(root));
    }

    private TreeNode mirrorCopy(TreeNode node) {
        if (node == null) {
            return null;
        }
        TreeNode copy = new TreeNode(node.val);
        copy.left = mirrorCopy(node.right);
        copy.right = mirrorCopy(node.left);
        return copy;
    }

    private boolean same(TreeNode first, TreeNode second) {
        if (first == null || second == null) {
            return first == second;
        }
        return first.val == second.val
            && same(first.left, second.left)
            && same(first.right, second.right);
    }
}

